update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p051","body":"یوں دل میں خواہشوں کے انبار رہتے ہیں\nکچھ لوگ رہتے ہیں ، کچھ آثار رہتے ہیں\n\nطشتِ فلک ستاروں سے لبریز سا ہے\nہم تو بس یونہی  ذرا بیزار رہتے ہیں\n\nہم خوابوں میں حقیقتوں کی شرابیں گھول کر\nشب بہ شب بےسایہِ بر سرِ دیوار رہتے ہیں\n\nاتنا مت بھولو کہ جب یاد آؤ تو فرصت نہ ملے\nاتنا مت یاد آؤ کہ ہم اکثر بےکار رہتے ہیں\n\nکیا تھا اگر تو کبھی لوٹ کے آیا ہوتا\nگُلوں کے سایوں میں بھی تو خار رہتے ہیں\n\nآپ کے دل میں رہ کر دیکھ لیا احمد ؔ\nاب جہاں رہتے ہیں بےسروکار رہتے ہیں"},{"slug":"tum-p052","body":"بجھے ارماں ڈوبی کشتیاں بہانے کی ہے\nبات ساری محمد کے گھرانے کی ہے\n\nجل اٹھتی ہیں تاریکیوں میں گھپ مشعلیں\nوہ شمع جو راہ سفر اس آشیانے کی ہے\n\nہماری تو ان ان سے ہیں عقیدتیں وابستہ\nجو ہستیاں پنچتن کے بتانے کی ہے\n\nجھک گئی ظلم کی تلوار اٹھ گیا حق کا علم\nدنیا بھی تو جنت کے شہزادے کی ہے"},{"slug":"tum-p053","body":"نہ آنکھ میں تمنا باقی ہے نہ بازوؤں میں طاقت ہے\nمگر اس دل بے سہارہ کو فقط تیری ہی چاہت ہے\n\nحیرت کہ کارِ ہستی میں اپنی یکساں شخصیت سے\nکسی کو بےحد نفرت ہے اور کسی کوعقیدت ہے\n\nتم ہمیں جو یاد آتے ہو بلاوجہ یونہی بیٹھے بیٹھے\nیہ کوئی فکر کی بات نہیں یہ بس پرانی عادت ہے\n\nیہ زندگی کے قافلوں کی ہیں تنہاروی کی منزلیں\nسب کی اپنی مسلئت ہے سب کی اپنی حلاوت ہے\n\nآ کہ دل اداس ہے ابھی نہیں تو کبھی نہیں\nتیرا بھولنا کوئی دوا نہیں، تیرا لوٹنا ہی شفاعت ہے\n\nیہ وصل اور فراق تو احمد ؔ خدا کا فیصلہ تھا\nوہ بھی اپنی قسمت تھی یہ بھی اپنی قسمت ہے"},{"slug":"tum-p054","body":"بارش ، دوست  ، دھواں اور سکوں\nدل میرا اداس ہے مگر جانے کیوں"},{"slug":"tum-p055","body":"دل جس سے ہار گیا\nوہ شخص تو پار گیا\n\nچہرے پہ پھول کھلے رہے\nدل کا معاملہ خار گیا\n\nجو شے مقدر ہی میں نہیں\nدل اسی شے پہ وار گیا\n\nعمر سکوں کی کھوج میں کٹی\nپر یہ تجربہ بھی بیزار گیا\n\nایک شخص کو اتنا چاہا\nہر شخص سے اعتبار گیا\n\nخواب نینوں کا راستہ بھول گئے\nنیند ایسی کھلی کہ خمار گیا\n\nجس میں تم نہ ملے احمدؔ\nوہ سارا جیون بےکار گیا"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
